body { animation: crisisPulse 0.3s infinite alternate, glitchTear 0.15s infinite; box-shadow: inset 0 0 200px rgba(255, 0, 0, 0.9); overflow: hidden; }

@keyframes crisisPulse {
  from { filter: blur(3px) contrast(1.5) saturate(2); opacity: 0.7; }
  to { filter: blur(8px) contrast(3.0) saturate(4); opacity: 1; }
}

@keyframes glitchTear {
  0% { transform: translate(0) skew(0deg); }
  20% { transform: translate(-8px, 8px) skew(-15deg); }
  40% { transform: translate(8px, -8px) skew(15deg); }
  60% { transform: translate(-4px, 4px) skew(0deg); }
  80% { transform: translate(4px, -4px) skew(10deg); }
  100% { transform: translate(0) skew(0deg); }
}

* { color: #ff3333 !important; text-shadow: 2px 2px 10px rgba(255,0,0,0.8); }
